      "pa": "ਸੜੇ ਅਨਾਜ ਤੋਂ ਕਣਕ-ਜੌ ਵਰਗੀਆਂ ਫਸਲਾਂ ਬਾਰੇ ਪਤਾ ਲੱਗਦਾ ਹੈ। ਮਣਕੇ, ਮੋਹਰਾਂ ਅਤੇ ਮਿਆਰੀ ਵੱਟੇ ਸ਼ਿਲਪ ਤੇ ਵਟਾਂਦਰੇ ਨੂੰ ਸਮਝਾਉਂਦੇ ਹਨ। ਕਾਲੀਬੰਗਾ ਵਿੱਚ ਹਲ ਨਾਲ ਵਾਹੇ ਖੇਤ ਦਾ ਸਬੂਤ ਮਿਲਿਆ; ਧੋਲਾਵੀਰਾ ਦੇ ਜਲਾਸ਼ਯ ਪਾਣੀ ਸੰਭਾਲਣ ਦੀ ਰਣਨੀਤੀ ਦੱਸਦੇ ਹਨ।",
      "en": "Charred grain helps identify crops such as wheat and barley. Beads, seals and standard weights help reconstruct craft production and exchange. Kalibangan has evidence of a ploughed field; Dholavira’s reservoirs show a different water-management strategy."
