      "pa": "ਰਣਜੀਤ ਸਿੰਘ ਨੇ 1799 ਵਿੱਚ ਲਾਹੌਰ ਉੱਤੇ ਕਬਜ਼ਾ ਕੀਤਾ ਅਤੇ 1801 ਵਿੱਚ ਮਹਾਰਾਜਾ ਬਣੇ। ਰਾਜਧਾਨੀ ਲਾਹੌਰ ਸੀ। ਕ੍ਰਮ ਕਾਰਡ ਬਣਾਓ: 1699 ਖ਼ਾਲਸਾ, 1708 ਬੰਦਾ ਸਿੰਘ ਨੂੰ ਭੇਜਣਾ, 1799 ਲਾਹੌਰ, 1801 ਮਹਾਰਾਜਾ। ਅੱਜ ਦੀਆਂ ਸਰਹੱਦਾਂ ਨੂੰ ਪੁਰਾਣੇ ਪੰਜਾਬ ਉੱਤੇ ਸਿੱਧਾ ਨਾ ਲਗਾਓ।",
      "en": "Ranjit Singh took Lahore in 1799 and became Maharaja in 1801; Lahore was the capital. Build chronology cards for 1699, 1708, 1799 and 1801. Avoid projecting today’s political boundaries directly onto the Punjab of earlier periods."
