      "en": "The Constituent Assembly adopted it on 26 November 1949; most provisions commenced on 26 January 1950. B. R. Ambedkar chaired the Drafting Committee, whereas Rajendra Prasad presided over the Assembly. Distinguish both dates and institutional roles."
