      "hi": "प्रस्तावना जनता को सत्ता का स्रोत बताती है और न्याय, स्वतंत्रता, समानता तथा बंधुता के लक्ष्य रखती है। गणराज्य का अर्थ वंशानुगत सम्राट के स्थान पर निर्वाचित राष्ट्राध्यक्ष की व्यवस्था है। लोकतंत्र में जनता प्रतिनिधि चुनती है; दोनों शब्दों का अर्थ एक नहीं है।",
      "pa": "ਪ੍ਰਸਤਾਵਨਾ ਲੋਕਾਂ ਨੂੰ ਸੱਤਾ ਦਾ ਸਰੋਤ ਅਤੇ ਨਿਆਂ, ਆਜ਼ਾਦੀ, ਸਮਾਨਤਾ ਤੇ ਭਾਈਚਾਰੇ ਨੂੰ ਟੀਚੇ ਦੱਸਦੀ ਹੈ। ਗਣਰਾਜ ਵਿੱਚ ਵਿਰਾਸਤੀ ਬਾਦਸ਼ਾਹ ਦੀ ਥਾਂ ਚੁਣਿਆ ਰਾਸ਼ਟਰ ਮੁਖੀ ਹੁੰਦਾ ਹੈ। ਲੋਕਤੰਤਰ ਵਿੱਚ ਲੋਕ ਨੁਮਾਇੰਦੇ ਚੁਣਦੇ ਹਨ; ਦੋਵੇਂ ਸ਼ਬਦ ਇਕੋ ਨਹੀਂ ਹਨ।",
      "en": "The Preamble locates authority in the people and sets goals of justice, liberty, equality and fraternity. A republic has an elected head of state rather than a hereditary monarch. Democracy concerns popular political participation; these concepts are related but not identical."
