    "correct": "B",
    "explanation": {
      "hi": "धन विधेयक केवल लोकसभा में प्रस्तुत होता है। राज्यसभा 14 दिन में सुझाव दे सकती है; लोकसभा उन सुझावों को स्वीकार करने के लिए बाध्य नहीं। लोकसभा अध्यक्ष प्रमाणन करते हैं। सभी वित्तीय विषय वाले विधेयकों को बिना अनुच्छेद 110 की शर्तें देखे धन विधेयक कहना गलत है।",
      "pa": "ਧਨ ਬਿੱਲ ਸਿਰਫ਼ ਲੋਕ ਸਭਾ ਵਿੱਚ ਆਉਂਦਾ ਹੈ। ਰਾਜ ਸਭਾ 14 ਦਿਨਾਂ ਵਿੱਚ ਸਿਫ਼ਾਰਸ਼ਾਂ ਕਰ ਸਕਦੀ ਹੈ; ਲੋਕ ਸਭਾ ਉਨ੍ਹਾਂ ਨੂੰ ਮੰਨਣ ਲਈ ਬੱਝੀ ਨਹੀਂ। ਲੋਕ ਸਭਾ ਸਪੀਕਰ ਪ੍ਰਮਾਣਿਤ ਕਰਦੇ ਹਨ। ਹਰ ਵਿੱਤੀ ਬਿੱਲ ਨੂੰ ਅਨੁਛੇਦ 110 ਦੀਆਂ ਸ਼ਰਤਾਂ ਬਿਨਾਂ ਧਨ ਬਿੱਲ ਨਾ ਕਹੋ।",
      "en": "A Money Bill originates only in Lok Sabha. Rajya Sabha may recommend changes within fourteen days, but Lok Sabha need not accept them. The Speaker certifies it. Not every bill mentioning finance meets the specific Article 110 conditions for a Money Bill."
    },
