      "en": "The Seventy-third Amendment gave rural Panchayats constitutional status. The Gram Sabha comprises registered village voters; the Gram Panchayat is an elected body. They are distinct. Panchayat terms are ordinarily five years, and the Eleventh Schedule lists relevant local subjects."
