      "hi": "360° घूर्णन लगभग 24 घंटे में होता है: 15° = एक घंटा और 1° = चार मिनट। अधिक पूर्व का स्थान सूर्य को पहले देखता है, इसलिए उसका स्थानीय सौर समय आगे होता है। 82½°E भारत का मानक मध्याह्न है; 82.5 × 4 = 330 मिनट अर्थात UTC से 5 घंटे 30 मिनट आगे। स्थानीय सौर समय और सरकारी समय अलग अवधारणाएँ हैं; मोबाइल का समय हर नगर के देशांतर पर नहीं बदलता।",
      "pa": "360° ਘੁੰਮਣ ਲਗਭਗ 24 ਘੰਟਿਆਂ ਵਿੱਚ ਹੁੰਦਾ ਹੈ: 15° ਇੱਕ ਘੰਟਾ ਅਤੇ 1° ਚਾਰ ਮਿੰਟ। ਪੂਰਬੀ ਥਾਂ ਸੂਰਜ ਨੂੰ ਪਹਿਲਾਂ ਵੇਖਦੀ ਹੈ, ਇਸ ਦਾ ਸਥਾਨਕ ਸੂਰਜੀ ਸਮਾਂ ਅੱਗੇ ਹੁੰਦਾ ਹੈ। 82½°E ਭਾਰਤ ਦਾ ਮਿਆਰੀ ਮੱਧਿਆਨ੍ਹ ਹੈ; 82.5 × 4 = 330 ਮਿੰਟ, ਭਾਵ UTC ਤੋਂ 5 ਘੰਟੇ 30 ਮਿੰਟ ਅੱਗੇ। ਸਥਾਨਕ ਸੂਰਜੀ ਸਮਾਂ ਅਤੇ ਸਰਕਾਰੀ ਸਮਾਂ ਵੱਖ ਹਨ; ਮੋਬਾਈਲ ਹਰ ਸ਼ਹਿਰ ਦੇ ਦੇਸ਼ਾਂਤਰ ਨਾਲ ਸਮਾਂ ਨਹੀਂ ਬਦਲਦਾ।",
      "en": "A 360° rotation takes about 24 hours: 15° corresponds to an hour and 1° to four minutes. Locations farther east have later local solar time because the Sun reaches them earlier. India’s standard meridian is 82½°E: 82.5 × 4 = 330 minutes, giving UTC+5:30. Local solar time and officially adopted clock time are different; a phone does not change its clock for every town’s longitude."
