      "hi": "पृथ्वी सूर्य की परिक्रमा लगभग 365¼ दिनों में करती है। अक्ष कक्षीय तल के लंब से लगभग 23½° झुका है। इसी झुकाव और परिक्रमा से सूर्यकिरणों का कोण तथा दिन की अवधि बदलती है। जून में उत्तरी गोलार्ध सूर्य की ओर झुका रहता है; वहाँ गर्मी और दक्षिण में सर्दी होती है। ऋतुओं को केवल सूर्य से दूरी बदलने का परिणाम कहना गलत है। विषुव के आसपास दिन और रात लगभग बराबर होते हैं; वायुमंडलीय प्रभावों से बिल्कुल 12 घंटे होना आवश्यक नहीं।",
      "pa": "ਧਰਤੀ ਸੂਰਜ ਦੀ ਪਰਿਕਰਮਾ ਲਗਭਗ 365¼ ਦਿਨਾਂ ਵਿੱਚ ਕਰਦੀ ਹੈ। ਧੁਰਾ ਕਕਸ਼ ਦੇ ਤਲ ਦੇ ਲੰਬ ਤੋਂ ਲਗਭਗ 23½° ਝੁਕਿਆ ਹੈ। ਝੁਕਾਅ ਤੇ ਪਰਿਕਰਮਾ ਨਾਲ ਕਿਰਨਾਂ ਦਾ ਕੋਣ ਅਤੇ ਦਿਨ ਦੀ ਲੰਬਾਈ ਬਦਲਦੇ ਹਨ। ਜੂਨ ਵਿੱਚ ਉੱਤਰੀ ਗੋਲਾਰਧ ਸੂਰਜ ਵੱਲ ਝੁਕਦਾ ਹੈ; ਉੱਥੇ ਗਰਮੀ ਅਤੇ ਦੱਖਣ ਵਿੱਚ ਸਰਦੀ ਹੁੰਦੀ ਹੈ। ਕੇਵਲ ਦੂਰੀ ਬਦਲਣ ਨਾਲ ਰੁੱਤਾਂ ਨਹੀਂ ਬਣਦੀਆਂ। ਵਿਸ਼ੁਵ ਨੇੜੇ ਦਿਨ-ਰਾਤ ਲਗਭਗ ਬਰਾਬਰ ਹੁੰਦੇ ਹਨ, ਬਿਲਕੁਲ 12 ਘੰਟੇ ਲਾਜ਼ਮੀ ਨਹੀਂ।",
      "en": "Earth revolves around the Sun in about 365¼ days. Its axis tilts roughly 23½° from the perpendicular to the orbital plane. Tilt and revolution change sunlight angle and day length. Around June the Northern Hemisphere tilts toward the Sun, producing northern summer and southern winter. Seasons are not explained simply by changes in Sun–Earth distance. Near an equinox day and night are approximately equal, not necessarily exactly twelve hours because of atmospheric effects."
