      "pa": "ਗੇਂਦ ਉੱਤੇ ਭੂਮੱਧ ਰੇਖਾ ਤੇ ਝੁਕਿਆ ਧੁਰਾ ਬਣਾਓ; ਟਾਰਚ ਨੂੰ ਸੂਰਜ ਮੰਨੋ। ਪਹਿਲਾਂ ਸਿਰਫ਼ ਗੇਂਦ ਘੁਮਾਓ, ਫਿਰ ਧੁਰੇ ਦੀ ਦਿਸ਼ਾ ਰੱਖ ਕੇ ਟਾਰਚ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਲਿਜਾਓ। ਦਿਨ-ਰਾਤ ਅਤੇ ਰੁੱਤ ਦੇ ਕਾਰਨ ਵੱਖ ਦਿੱਸਣਗੇ। ਦੋ ਦੇਸ਼ਾਂਤਰਾਂ ਦਾ ਅੰਤਰ ਕੱਢ ਕੇ ਚਾਰ ਮਿੰਟ ਨਾਲ ਗੁਣਾ ਕਰੋ; ਪੂਰਬ ਦਾ ਸਮਾਂ ਅੱਗੇ ਹੈ। ਧੁਰਾ ਸਿੱਧਾ ਹੋਵੇ ਤਾਂ ਅੱਜ ਵਰਗਾ ਵੱਡਾ ਰੁੱਤੀ ਅੰਤਰ ਨਾ ਹੋਵੇ, ਪਰ ਘੁੰਮਣ ਨਾਲ ਦਿਨ-ਰਾਤ ਰਹਿਣਗੇ।",
