    "correct": "C",
    "explanation": {
      "hi": "पृथ्वी की सतह सौर ऊर्जा सोखकर वायुमंडल को नीचे से गर्म करती है। गर्म हवा सामान्यतः फैलती और ऊपर उठती है; ठंडी घनी हवा नीचे आती है। मगर सतह का दबाव ऊपर मौजूद पूरे वायु स्तंभ के भार से बनता है, इसलिए केवल तापमान देखकर हर दबाव प्रणाली नहीं समझी जा सकती। ऊँचाई बढ़ने पर वायु स्तंभ छोटा होता है और दबाव घटता है। समदाब रेखाएँ बराबर दबाव जोड़ती हैं; पास रेखाएँ मजबूत दबाव प्रवणता दिखाती हैं।",
      "pa": "ਧਰਤੀ ਦੀ ਸਤਹ ਸੂਰਜੀ ਊਰਜਾ ਸੋਖ ਕੇ ਹਵਾ ਨੂੰ ਹੇਠੋਂ ਗਰਮ ਕਰਦੀ ਹੈ। ਗਰਮ ਹਵਾ ਆਮ ਤੌਰ ਤੇ ਫੈਲ ਕੇ ਚੜ੍ਹਦੀ ਹੈ; ਠੰਡੀ ਘਣੀ ਹਵਾ ਹੇਠਾਂ ਆਉਂਦੀ ਹੈ। ਸਤਹ ਦਾ ਦਬਾਅ ਪੂਰੇ ਉੱਪਰਲੇ ਹਵਾ-ਸਤੰਭ ਦੇ ਭਾਰ ਨਾਲ ਬਣਦਾ ਹੈ; ਕੇਵਲ ਤਾਪਮਾਨ ਹਰ ਪ੍ਰਣਾਲੀ ਨਹੀਂ ਸਮਝਾਉਂਦਾ। ਉਚਾਈ ਨਾਲ ਦਬਾਅ ਘਟਦਾ ਹੈ। ਸਮਦਬਾਅ ਰੇਖਾਵਾਂ ਬਰਾਬਰ ਦਬਾਅ ਜੋੜਦੀਆਂ ਹਨ; ਨੇੜਲੀਆਂ ਰੇਖਾਵਾਂ ਵੱਧ ਦਬਾਅ ਢਾਲ ਦੱਸਦੀਆਂ ਹਨ।",
      "en": "The surface absorbs solar energy and helps heat the atmosphere from below. Warm air generally expands and rises; cooler dense air descends. Surface pressure nevertheless reflects the weight of the entire overlying air column, so temperature alone cannot explain every pressure system. Pressure decreases with altitude. Isobars join equal pressure; closely spaced isobars indicate a stronger pressure gradient."
    },
    "difficulty": "medium",
    "year": 2022
