    "correct": "C",
    "explanation": {
      "hi": "भूमध्य क्षेत्र में गर्म हवा उठने से निम्न दबाव बनता है; लगभग 30° पर उतरती हवा उपोष्ण उच्च दबाव से जुड़ी है। इन उच्च दबावों से भूमध्य की ओर व्यापारिक पवनें और मध्य अक्षांशों की ओर पछुआ पवनें बहती हैं। लगभग 60° के पास उपध्रुवीय निम्न दबाव मिलता है। यह आदर्श तीन-कोशिका मॉडल है; महाद्वीप, समुद्र और ऋतु वास्तविक पट्टियों को बदलते हैं। व्यापारिक पवनों का मिलन क्षेत्र ITCZ वर्षा और मानसून को समझने में उपयोगी है।",
      "pa": "ਭੂਮੱਧ ਨੇੜੇ ਗਰਮ ਹਵਾ ਚੜ੍ਹ ਕੇ ਘੱਟ ਦਬਾਅ ਬਣਾਉਂਦੀ ਹੈ; ਲਗਭਗ 30° ਉੱਤੇ ਉਤਰਦੀ ਹਵਾ ਉਪਉਸ਼ਣ ਉੱਚ ਦਬਾਅ ਨਾਲ ਜੁੜਦੀ ਹੈ। ਉੱਥੋਂ ਭੂਮੱਧ ਵੱਲ ਵਪਾਰਕ ਅਤੇ ਮੱਧ ਅਕਸ਼ਾਂਸ਼ਾਂ ਵੱਲ ਪੱਛਮੀ ਪਵਨਾਂ ਚੱਲਦੀਆਂ ਹਨ। 60° ਨੇੜੇ ਉਪਧਰੁਵੀ ਘੱਟ ਦਬਾਅ ਹੈ। ਇਹ ਆਦਰਸ਼ ਤਿੰਨ-ਕੋਸ਼ਿਕਾ ਮਾਡਲ ਹੈ; ਧਰਤੀ-ਸਮੁੰਦਰ ਤੇ ਰੁੱਤਾਂ ਇਸ ਨੂੰ ਬਦਲਦੀਆਂ ਹਨ। ITCZ ਵਪਾਰਕ ਪਵਨਾਂ ਦੇ ਮਿਲਣ ਦਾ ਖੇਤਰ ਹੈ।",
      "en": "Rising warm air contributes to equatorial low pressure; descending air around 30° relates to subtropical highs. Trade winds flow toward the Equator and westerlies toward middle latitudes. Subpolar lows occur around 60°. This is an idealised three-cell model: land, oceans and seasons alter actual belts. The ITCZ, where trade winds converge, helps explain rainfall and monsoon circulation."
    },
    "difficulty": "medium",
    "year": 2022
