    "explanation": {
      "hi": "भूपर्पटी बाहरी पतली परत है, उसके नीचे मैंटल और फिर क्रोड है। महासागरीय पर्पटी सामान्यतः महाद्वीपीय पर्पटी से पतली और अधिक घनी होती है। स्थलमंडल पर्पटी और कठोर ऊपरी मैंटल से बनता है; यह प्लेटों में विभाजित है। उसके नीचे दुर्बलतामंडल में चट्टानें लंबे समय में नम्य व्यवहार करती हैं; उसे पूरा द्रव महासागर कहना गलत है। प्रत्यक्ष खनन सीमित है, इसलिए भूकंपीय तरंगें आंतरिक संरचना का महत्त्वपूर्ण प्रमाण हैं।",
      "pa": "ਭੂਪਰਪਟੀ ਬਾਹਰੀ ਪਤਲੀ ਪਰਤ ਹੈ; ਹੇਠਾਂ ਮੈਂਟਲ ਤੇ ਫਿਰ ਕੋਰ ਹੈ। ਸਮੁੰਦਰੀ ਪਰਪਟੀ ਆਮ ਤੌਰ ਤੇ ਮਹਾਦੀਪੀ ਨਾਲੋਂ ਪਤਲੀ ਤੇ ਵੱਧ ਘਣੀ ਹੈ। ਸਥਲਮੰਡਲ ਪਰਪਟੀ ਅਤੇ ਸਖ਼ਤ ਉੱਪਰਲੇ ਮੈਂਟਲ ਦਾ ਬਣਦਾ ਅਤੇ ਪਲੇਟਾਂ ਵਿੱਚ ਵੰਡਿਆ ਹੈ। ਹੇਠਲਾ ਦੁਰਬਲਮੰਡਲ ਲੰਮੇ ਸਮੇਂ ਵਿੱਚ ਲਚਕੀਲਾ ਵਰਤਾਅ ਕਰਦਾ ਹੈ; ਇਹ ਸਾਰਾ ਤਰਲ ਸਮੁੰਦਰ ਨਹੀਂ। ਭੂਚਾਲੀ ਤਰੰਗਾਂ ਅੰਦਰਲੀ ਬਣਤਰ ਦਾ ਅਹਿਮ ਸਬੂਤ ਹਨ।",
      "en": "The crust is a thin outer layer over the mantle and core. Oceanic crust is generally thinner and denser than continental crust. The lithosphere includes crust and rigid upper mantle and is divided into plates. Beneath it the asthenosphere deforms over long timescales; it is not simply a wholly liquid ocean. Seismic waves provide important evidence because direct drilling reaches only a small fraction of Earth’s depth."
    },
    "difficulty": "medium",
    "year": 2022
