      "hi": "अपसारी सीमा पर प्लेटें दूर जाती हैं और महासागरीय रिज पर नई पर्पटी बन सकती है। अभिसारी सीमा पर प्लेटें मिलती हैं: महासागरीय प्लेट का अवतलन या महाद्वीपों की टक्कर संभव है। भारतीय और यूरेशियाई प्लेटों की टक्कर हिमालय से जुड़ी है। रूपांतरण सीमा पर प्लेटें एक-दूसरे के पास से खिसकती हैं; यहाँ भूकंप आ सकते हैं पर नई पर्पटी बनना आवश्यक नहीं। प्लेट गति मिलीमीटर–सेंटीमीटर प्रति वर्ष की हो सकती है, फिर भी लाखों वर्षों में बड़े पर्वत बनते हैं।",
      "pa": "ਅਪਸਾਰੀ ਹੱਦ ਉੱਤੇ ਪਲੇਟਾਂ ਦੂਰ ਜਾਂਦੀਆਂ ਅਤੇ ਸਮੁੰਦਰੀ ਰਿੱਜ ਉੱਤੇ ਨਵੀਂ ਪਰਪਟੀ ਬਣ ਸਕਦੀ ਹੈ। ਅਭਿਸਾਰੀ ਹੱਦ ਉੱਤੇ ਪਲੇਟਾਂ ਮਿਲਦੀਆਂ ਹਨ; ਸਮੁੰਦਰੀ ਪਲੇਟ ਹੇਠਾਂ ਜਾ ਸਕਦੀ ਜਾਂ ਮਹਾਦੀਪ ਟਕਰਾ ਸਕਦੇ ਹਨ। ਭਾਰਤੀ ਤੇ ਯੂਰੇਸ਼ੀਆਈ ਪਲੇਟਾਂ ਦੀ ਟੱਕਰ ਹਿਮਾਲਿਆ ਨਾਲ ਜੁੜੀ ਹੈ। ਰੂਪਾਂਤਰਨ ਹੱਦ ਉੱਤੇ ਪਲੇਟਾਂ ਕੋਲੋਂ ਖਿਸਕਦੀਆਂ ਹਨ; ਭੂਚਾਲ ਹੋ ਸਕਦੇ ਪਰ ਨਵੀਂ ਪਰਪਟੀ ਲਾਜ਼ਮੀ ਨਹੀਂ ਬਣਦੀ। ਛੋਟੀ ਸਾਲਾਨਾ ਗਤੀ ਲੱਖਾਂ ਸਾਲਾਂ ਵਿੱਚ ਪਹਾੜ ਬਣਾਉਂਦੀ ਹੈ।",
      "en": "At divergent boundaries plates separate and new crust can form at ocean ridges. At convergent boundaries plates approach: oceanic subduction or continental collision may occur. Collision of the Indian and Eurasian plates relates to the Himalaya. At transform boundaries plates slide past one another; earthquakes can occur without crust creation. Millimetres-to-centimetres of annual movement still produce major mountains over geological time."
