    "correct": "A",
    "explanation": {
      "hi": "अपक्षय चट्टान का उसी स्थान पर टूटना या रासायनिक बदलना है। अपरदन में पदार्थ हटता और बहता है; निक्षेप में परिवहन की ऊर्जा घटने पर पदार्थ जमा होता है। ताप विस्तार, पाला और जड़ों का दबाव भौतिक टूटन बढ़ा सकते हैं। घुलना और ऑक्सीकरण रासायनिक अपक्षय हैं। एक टूटी चट्टान तब तक अपरदित नहीं कहलाती जब तक पदार्थ हटे नहीं। जलवायु, चट्टान और वनस्पति तय करते हैं कि कौन प्रक्रिया अधिक सक्रिय होगी।",
      "pa": "ਅਪਖੰਡਨ ਚੱਟਾਨ ਦਾ ਉਸੇ ਥਾਂ ਟੁੱਟਣਾ ਜਾਂ ਰਸਾਇਣਕ ਬਦਲਣਾ ਹੈ। ਕਟਾਅ ਵਿੱਚ ਪਦਾਰਥ ਹਟ ਕੇ ਚੱਲਦਾ ਹੈ; ਜਮਾਵ ਵਿੱਚ ਊਰਜਾ ਘਟਣ ਨਾਲ ਪਦਾਰਥ ਇਕੱਠਾ ਹੁੰਦਾ ਹੈ। ਤਾਪ ਦਾ ਫੈਲਾਅ, ਪਾਲਾ ਅਤੇ ਜੜ੍ਹਾਂ ਭੌਤਿਕ ਟੁੱਟਣ ਵਧਾਉਂਦੀਆਂ ਹਨ। ਘੁਲਣਾ ਤੇ ਆਕਸੀਕਰਨ ਰਸਾਇਣਕ ਅਪਖੰਡਨ ਹਨ। ਟੁੱਟੀ ਚੱਟਾਨ ਦਾ ਪਦਾਰਥ ਹਟੇ ਬਿਨਾਂ ਕਟਾਅ ਨਹੀਂ। ਜਲਵਾਯੂ, ਚੱਟਾਨ ਅਤੇ ਬਨਸਪਤੀ ਪ੍ਰਕਿਰਿਆ ਦੀ ਤੀਬਰਤਾ ਬਦਲਦੇ ਹਨ।",
      "en": "Weathering breaks or chemically alters rock in place. Erosion removes and transports material; deposition accumulates it as transport energy falls. Thermal expansion, frost and roots can cause physical breakdown, while dissolution and oxidation are chemical weathering. Broken rock is not necessarily eroded until it is removed. Climate, rock properties and vegetation influence which processes dominate."
    },
    "difficulty": "medium",
    "year": 2022
