      "pa": "ਕਾਰਬਨ ਡਾਈਆਕਸਾਈਡ ਵਾਲਾ ਪਾਣੀ ਚੂਨਾ ਪੱਥਰ ਘੋਲ ਕੇ ਕਾਰਸਟ ਗੁਫ਼ਾਵਾਂ ਤੇ ਧੱਸੇ ਖੇਤਰ ਬਣਾਉਂਦਾ ਹੈ। ਟਪਕਦੇ ਪਾਣੀ ਤੋਂ ਛੱਤ ਉੱਤੇ ਸਟੈਲੈਕਟਾਈਟ ਅਤੇ ਫਰਸ਼ ਉੱਤੇ ਸਟੈਲੈਗਮਾਈਟ ਬਣ ਸਕਦੇ ਹਨ। ਹਿਮਨਦ ਦਾ ਰਗੜਨਾ ਤੇ ਉਖਾੜਨਾ U-ਆਕਾਰ ਘਾਟੀਆਂ ਬਣਾਉਂਦਾ ਹੈ; ਜਮਿਆ ਮਿਲਿਆ ਅਵਸਾਦ ਮੋਰੇਨ ਹੈ। V ਅਤੇ U ਘਾਟੀ ਨੂੰ ਕੱਟ ਦੇ ਚਿੱਤਰ ਨਾਲ ਯਾਦ ਕਰੋ। ਅਸਲੀ ਘਾਟੀਆਂ ਕਈ ਪੁਰਾਣੀਆਂ ਪ੍ਰਕਿਰਿਆਵਾਂ ਦਾ ਮਿਲਾਪ ਹੋ ਸਕਦੀਆਂ ਹਨ।",
