      "hi": "सूखे कम वनस्पति वाले क्षेत्र में पवन छोटे कण उड़ा सकती है। घर्षण चट्टान घिसता है; निक्षेप से टिब्बे बनते हैं। महीन पवन-जमा गाद को लोएस कहते हैं। गुरुत्व से ढाल पर पदार्थ का नीचे खिसकना बृहद संचलन है; इसे नदी परिवहन न समझें। तैयारी में पाँच स्तंभ लिखें: एजेंट, प्रक्रिया, भूआकार, चित्र और उदाहरण। पौधों का आवरण तथा उचित भूमि उपयोग मिट्टी का कटाव घटाते हैं, जबकि ढाल काटना और पेड़ हटाना जोखिम बढ़ा सकते हैं।",
