    "correct": "B",
    "explanation": {
      "hi": "नदी मोड़ के बाहर तेज प्रवाह सामान्यतः कटाव करता है और भीतर धीमे प्रवाह से अवसाद जमा होता है। मोड़ की गर्दन कट जाए और पुराना चाप अलग हो जाए तो गोखुर झील बन सकती है। नदी के मुख पर अवसाद का निक्षेप लहरों और ज्वार के हटाने से अधिक हो तो डेल्टा विकसित हो सकता है। हर नदी मुख डेल्टा नहीं: मजबूत ज्वार या गहरा डूबा मुख ज्वारनदमुख दे सकता है। रेखाचित्र में बाहर कटाव, भीतर निक्षेप जरूर लिखें।",
      "pa": "ਨਦੀ ਦੇ ਮੋੜ ਦੇ ਬਾਹਰ ਤੇਜ਼ ਵਹਾਅ ਆਮ ਤੌਰ ਤੇ ਕਟਾਅ ਅਤੇ ਅੰਦਰ ਹੌਲਾ ਵਹਾਅ ਜਮਾਵ ਕਰਦਾ ਹੈ। ਗਰਦਨ ਕੱਟ ਕੇ ਪੁਰਾਣਾ ਚਾਪ ਅਲੱਗ ਹੋਵੇ ਤਾਂ ਗੋਖੁਰ ਝੀਲ ਬਣ ਸਕਦੀ ਹੈ। ਨਦੀ ਮੁਹਾਣੇ ਉੱਤੇ ਲਹਿਰਾਂ-ਜਵਾਰ ਦੇ ਹਟਾਉਣ ਨਾਲੋਂ ਵੱਧ ਅਵਸਾਦ ਜਮੇ ਤਾਂ ਡੈਲਟਾ ਬਣ ਸਕਦਾ ਹੈ। ਹਰ ਮੁਹਾਣਾ ਡੈਲਟਾ ਨਹੀਂ; ਤਿੱਖੇ ਜਵਾਰ ਜਾਂ ਡੂੰਘਾ ਡੁੱਬਿਆ ਮੁਹਾਣਾ ਜਵਾਰਨਦ ਮੁਹਾਣਾ ਹੋ ਸਕਦਾ ਹੈ। ਚਿੱਤਰ ਵਿੱਚ ਬਾਹਰ ਕਟਾਅ ਤੇ ਅੰਦਰ ਜਮਾਵ ਲਿਖੋ।",
      "en": "Flow commonly erodes the outer bank of a bend and deposits sediment on the inner bank. Cutting through the meander neck can isolate an oxbow lake. A delta may grow where river sediment supply exceeds removal by waves and tides. Not every mouth has a delta: strong tidal action or a drowned deep mouth may favour an estuary. Label outer-bank erosion and inner-bank deposition on your diagram."
    },
