      "hi": "महाद्वीपीय शेल्फ तट के पास उथला डूबा विस्तार है; उसके आगे ढाल गहरे महासागर तक उतरती है। गहरे मैदान के बीच रिज उठ सकते हैं और अवतलन से गहरी खाइयाँ बन सकती हैं। शेल्फ पर प्रकाश और पोषक पदार्थ मत्स्य उत्पादन में मदद करते हैं, पर उत्पादकता जगह अनुसार बदलती है। समुद्री खाई नदी घाटी नहीं और मध्य-महासागरीय रिज हिमालय जैसी महाद्वीपीय टक्कर का समान परिणाम नहीं है। समुद्र तल का प्रोफाइल बनाकर इनका क्रम लिखें।",
      "pa": "ਮਹਾਦੀਪੀ ਸ਼ੈਲਫ਼ ਤੱਟ ਨੇੜੇ ਉਥਲਾ ਡੁੱਬਿਆ ਵਿਸਥਾਰ ਹੈ; ਅੱਗੇ ਢਲਾਣ ਡੂੰਘੇ ਮਹਾਸਾਗਰ ਵੱਲ ਜਾਂਦੀ ਹੈ। ਡੂੰਘੇ ਮੈਦਾਨ ਵਿੱਚ ਰਿੱਜ ਅਤੇ ਅਵਤਲਨ ਨਾਲ ਖਾਈਆਂ ਬਣ ਸਕਦੀਆਂ ਹਨ। ਸ਼ੈਲਫ਼ ਦਾ ਚਾਨਣ ਤੇ ਪੋਸ਼ਕ ਮੱਛੀ ਉਤਪਾਦਨ ਲਈ ਮਦਦ ਕਰਦੇ ਹਨ, ਪਰ ਥਾਂ ਅਨੁਸਾਰ ਫ਼ਰਕ ਹੈ। ਸਮੁੰਦਰੀ ਖਾਈ ਨਦੀ ਘਾਟੀ ਨਹੀਂ; ਸਮੁੰਦਰੀ ਰਿੱਜ ਹਿਮਾਲਿਆ ਵਾਲੀ ਮਹਾਦੀਪੀ ਟੱਕਰ ਨਹੀਂ। ਤਲ ਦਾ ਪ੍ਰੋਫਾਈਲ ਬਣਾਓ।",
