    "explanation": {
      "hi": "महासागरीय धाराएँ बड़े पैमाने पर जल की दिशा वाली गति हैं। सतही धाराओं पर पवन, कोरिओलिस और महाद्वीपीय आकृति असर डालते हैं; गहरी परिसंचरण में तापमान और लवणता से घनत्व के अंतर महत्त्वपूर्ण हैं। गर्म और ठंडी धारा का नाम आसपास के पानी की तुलना से है। उपवेलन गहरा पोषक जल ऊपर ला सकता है और मत्स्य क्षेत्रों को समृद्ध कर सकता है। धारा से तटीय जलवायु बदल सकती है, पर उसका परिणाम पवन तथा स्थानीय स्थितियों के साथ पढ़ें।",
      "pa": "ਸਮੁੰਦਰੀ ਧਾਰਾਵਾਂ ਪਾਣੀ ਦੀ ਵੱਡੇ ਪੱਧਰ ਉੱਤੇ ਦਿਸ਼ਾਵਾਰ ਗਤੀ ਹਨ। ਸਤਹ ਉੱਤੇ ਪਵਨ, ਕੋਰੀਓਲਿਸ ਤੇ ਮਹਾਦੀਪਾਂ ਦੀ ਬਣਤਰ ਅਸਰ ਕਰਦੇ ਹਨ; ਡੂੰਘੇ ਵਹਾਅ ਵਿੱਚ ਤਾਪ ਤੇ ਖਾਰਾਪਣ ਤੋਂ ਘਣਤਾ ਦਾ ਅੰਤਰ ਮਹੱਤਵਪੂਰਨ ਹੈ। ਗਰਮ-ਠੰਡੀ ਧਾਰਾ ਆਲੇ-ਦੁਆਲੇ ਦੇ ਪਾਣੀ ਨਾਲ ਤੁਲਨਾ ਹੈ। ਉਪਵੈਲਿੰਗ ਡੂੰਘਾ ਪੋਸ਼ਕ ਪਾਣੀ ਉੱਪਰ ਲਿਆ ਕੇ ਮੱਛੀ ਖੇਤਰ ਸੁਧਾਰ ਸਕਦੀ ਹੈ। ਤੱਟ ਦੀ ਜਲਵਾਯੂ ਲਈ ਧਾਰਾਵਾਂ ਨੂੰ ਹਵਾ ਤੇ ਸਥਾਨਕ ਹਾਲਤਾਂ ਨਾਲ ਜੋੜੋ।",
      "en": "Currents are large-scale directed movements of ocean water. Winds, Coriolis and continental geometry affect surface currents; density differences caused by temperature and salinity matter for deep circulation. Warm/cold labels are relative to surrounding water. Upwelling can bring nutrient-rich deep water upward and support productive fishing grounds. Currents influence coastal climate, but interpret their effects together with winds and local conditions."
    },
