      "hi": "समुद्र तल का अचानक विस्थापन, जैसे कुछ बड़े समुद्री भूकंपों में, सुनामी पैदा कर सकता है। हर भूकंप सुनामी नहीं बनाता। गहरे समुद्र में सुनामी लंबी तरंगदैर्घ्य वाली कम ऊँचाई की हो सकती है, पर तट के उथले पानी में बढ़ सकती है। इसे सामान्य हवा वाली लहर या नियमित ज्वार न समझें। तीन पंक्तियों की तुलना बनाएँ: लहर–हवा, ज्वार–गुरुत्व, सुनामी–अचानक विस्थापन। तटीय खतरे के लिए आधिकारिक चेतावनी और निकासी मार्ग का पालन करें।",
