      "hi": "पंजाब की बड़ी वर्षा भागीदारी दक्षिण-पश्चिम मानसून से आती है। पश्चिमी विक्षोभ शीतकाल में वर्षा और हिमालय में हिमपात दे सकते हैं। शीतकालीन पानी रबी फसलों के लिए उपयोगी हो सकता है, पर अत्यधिक बारिश, ओले या हवा नुकसान भी करते हैं। एक ही प्रतिशत सभी जिलों और वर्षों में न मानें; अद्यतन आँकड़े IMD से लें। वर्षा की कमी और भूजल के लंबे गिरावट क्रम को एक ही चीज न समझें: सिंचाई की निकासी भी कारण है।",
      "pa": "ਪੰਜਾਬ ਦੀ ਵੱਡੀ ਵਰਖਾ ਦੱਖਣ-ਪੱਛਮੀ ਮਾਨਸੂਨ ਤੋਂ ਹੈ। ਪੱਛਮੀ ਵਿਘਨ ਸਰਦੀ ਵਿੱਚ ਮੀਂਹ ਅਤੇ ਹਿਮਾਲਿਆ ਵਿੱਚ ਬਰਫ਼ ਦੇ ਸਕਦੇ ਹਨ। ਸਰਦੀ ਦਾ ਪਾਣੀ ਰਬੀ ਲਈ ਲਾਭਦਾਇਕ ਹੋ ਸਕਦਾ ਹੈ, ਪਰ ਵੱਧ ਮੀਂਹ, ਗੜੇ ਜਾਂ ਹਵਾ ਨੁਕਸਾਨ ਕਰ ਸਕਦੇ ਹਨ। ਹਰ ਜ਼ਿਲ੍ਹੇ ਤੇ ਸਾਲ ਲਈ ਇੱਕੋ ਫ਼ੀਸਦੀ ਨਾ ਮੰਨੋ; ਨਵੇਂ ਅੰਕੜੇ IMD ਤੋਂ ਲਓ। ਵਰਖਾ ਦੀ ਘਾਟ ਅਤੇ ਲੰਮੀ ਭੂਜਲ ਗਿਰਾਵਟ ਇੱਕ ਨਹੀਂ; ਸਿੰਚਾਈ ਨਿਕਾਸੀ ਵੀ ਕਾਰਨ ਹੈ।",
      "en": "Punjab obtains a major share of rainfall from the southwest monsoon. Western disturbances can bring winter rain and Himalayan snow. Winter water may help rabi crops, but excessive rain, hail or wind can cause damage. Do not apply one percentage to every district and year; use updated IMD data. Low rainfall and long-term groundwater decline are different: irrigation extraction also matters."
